// Orthographic to Equirectangular — Geo, route: jsx
// Source: orthographic-to-equirectangular
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';

/** One full out-and-back sweep, matching the source notebook's 480 frames at 60fps. */
const CYCLE_MS = 8000;
const CAPTION_SPACE = 18;
const CAPTION_MIN_WIDTH = 420;

const sphere: d3.GeoSphere = { type: 'Sphere' };

/** Five vertices so adaptive resampling has segments to subdivide as the globe bends. */
const equator: d3.GeoGeometryObjects = {
  type: 'LineString',
  coordinates: [
    [-180, 0],
    [-90, 0],
    [0, 0],
    [90, 0],
    [180, 0]
  ]
};

// 15 degrees rather than the notebook's 10: the path string is rebuilt every frame, and
// the denser grid costs twice the time per frame for a wireframe that reads the same.
const graticule = d3.geoGraticule().step([15, 15])();

// @types/d3-geo declares these as factories returning a raw projection; at runtime they
// ARE the raw projection. One cast each at this boundary keeps the rest of the file strict.
const orthographicRaw = d3.geoOrthographicRaw as unknown as d3.GeoRawProjection;
const equirectangularRaw = d3.geoEquirectangularRaw as unknown as d3.GeoRawProjection;

/**
 * Blends the two RAW projections, not their outputs, so every point moves along a straight
 * line in projected space. Nothing is clipped, so at alpha 0 the far hemisphere folds
 * exactly onto the near one and the graticule reads as a single wireframe globe.
 */
function blendedProjection(alpha: number, width: number, height: number): d3.GeoProjection {
  const orthographicScale = width / 4;
  const equirectangularScale = (width - 2) / (2 * Math.PI);
  return d3
    .geoProjection((x, y) => {
      const [x0, y0] = orthographicRaw(x, y);
      const [x1, y1] = equirectangularRaw(x, y);
      return [x0 + alpha * (x1 - x0), y0 + alpha * (y1 - y0)];
    })
    .scale(orthographicScale + alpha * (equirectangularScale - orthographicScale))
    .translate([width / 2, height / 2])
    .rotate([10 * (1 - alpha), -20 * (1 - alpha)])
    .precision(0.4);
}

export default function OrthographicToEquirectangular({ width }: { width: number }) {
  const height = Math.round(width / 1.8);
  const [alpha, setAlpha] = useState(0);

  useEffect(() => {
    const timer = d3.timer((elapsed) => {
      const phase = (elapsed % CYCLE_MS) / CYCLE_MS;
      setAlpha(d3.easeCubic(phase < 0.5 ? 2 * phase : 2 - 2 * phase));
    });
    return () => timer.stop();
  }, []);

  const shapes = useMemo(() => {
    if (width === 0) return { grid: '', outline: '', line: '' };
    const path = d3.geoPath(blendedProjection(alpha, width, height));
    return {
      grid: path(graticule) ?? '',
      outline: path(sphere) ?? '',
      line: path(equator) ?? ''
    };
  }, [alpha, width, height]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="A graticule globe morphing continuously between the orthographic and equirectangular projections, with the equator highlighted"
    >
      <path d={shapes.grid} fill="none" stroke="var(--muted)" strokeWidth={0.6} opacity={0.7} />
      <path d={shapes.outline} fill="none" stroke="var(--text)" strokeWidth={1.25} />
      <path d={shapes.line} fill="none" stroke="var(--accent)" strokeWidth={1.75} />
      {width >= CAPTION_MIN_WIDTH && (
        <text
          x={width / 2}
          y={height - CAPTION_SPACE / 3}
          textAnchor="middle"
          fontSize={11}
          fill="var(--muted)"
          aria-hidden="true"
        >
          orthographic · equirectangular · blending the raw projections at alpha{' '}
          {alpha.toFixed(2)}
        </text>
      )}
    </svg>
  );
}
